"""Freeze MOD production before new numeric and typed public-dispatch observation."""
import json,math,struct,random,hashlib,itertools
from pathlib import Path
from datetime import datetime,timezone
import gen_broad_typed_20260929 as g
root=g.ROOT;out=root/'smart-fuzzer/runs/w111-mod-production-independent-20260929';out.mkdir(exist_ok=True);assert not(out/'candidate-freeze.json').exists()
rng=random.Random(202609293308);bits=lambda x:'0x'+struct.pack('>d',x).hex();decode=lambda b:struct.unpack('>d',b.to_bytes(8,'big'))[0]
prior=set()
for p in (root/'smart-fuzzer/runs').glob('w111-mod-*/answers-mod.json'):prior.update(tuple(r['args'])for r in json.loads(p.read_text(encoding='utf-8-sig'))['witnesses'])
rows=[]
for i in range(2400):
 de=rng.randrange(-1022,-972);d=math.ldexp(1.,de)
 if i%3:d=decode(int(bits(d),16)+rng.randint(1,7000))
 q=rng.choice([2.**26-1,2.**26,2.**26+1,rng.uniform(.5,1.2e12)])
 x=d*q+math.ldexp(rng.uniform(0,2),-1022)
 for sx,sd in [(1,1),(-1,1),(1,-1),(-1,-1)]:rows.append((sx*x,sd*d))
for i in range(2400):
 x=math.ldexp(rng.uniform(1,2),rng.randrange(-1022,1023))*rng.choice([-1,1]);d=math.ldexp(rng.uniform(1,2),rng.randrange(-1022,1023))*rng.choice([-1,1]);rows.append((x,d))
encoded=list(dict.fromkeys(tuple(map(bits,r))for r in rows if all(math.isfinite(x) and abs(x)>=2**-1022 for x in r)));encoded=[r for r in encoded if r not in prior];rng.shuffle(encoded)
p=out/'batch-mod.json';p.write_text(json.dumps({'function':'MOD','probes':[{'probe':{'id':f'w111mod-production-{i:05d}','args':r}}for i,r in enumerate(encoded)]},separators=(',',':')),encoding='utf-8')
paths=['crates/oxfunc_core/src/functions/mod_fn.rs','formal/lean/OxFunc/RemainderPublication.lean','formal/lean/OxFunc/Functions/ModFn.lean','crates/oxfunc_core/tests/w111_mod_publication.rs','crates/oxfunc_core/tests/fixtures/w111_mod_publication.json']
freeze={'frozen_utc':datetime.now(timezone.utc).isoformat(),'source_sha256':{p:hashlib.sha256((root/p).read_bytes()).hexdigest()for p in paths},'numeric_rows':len(encoded),'seed':202609293308,'prior_numeric_overlap':0,'batch_sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
for src in paths:(out/(Path(src).name+'.snapshot')).write_bytes((root/src).read_bytes())
(out/'candidate-freeze.json').write_text(json.dumps(freeze,indent=2),encoding='utf-8')
g.cases.clear();g.TRANCHE='w111-mod-production-typed-20260929'
vals=[g.n(-7.5),g.n(0.),g.n(2.25),g.t('3.5'),g.t(''),g.t('x'),g.b(True),g.b(False),g.blank(),g.missing(),g.e('Num'),g.e('Div0'),g.e('Ref')]
for i,(a,b)in enumerate(itertools.product(vals,repeat=2)):
 g.emit('MOD',f'direct-{i}',[a,b],axis='typed_discovery')
 if a['kind']!='missing_arg'and b['kind']!='missing_arg':g.emit('MOD',f'ref-{i}',[g.r('B210'),g.r('C210')],[g.fix('B210',a),g.fix('C210',b)],axis='typed_reference_discovery')
for i,raw in enumerate(encoded[:20]):
 a,b=[g.n(decode(int(v,16)))for v in raw]
 g.emit('MOD',f'unit-arrays-{i}',[g.a([[a]]),g.a([[b]])],axis='numeric_array_binding')
 g.emit('MOD',f'row-col-{i}',[g.a([[a,g.n(7.)]]),g.a([[b],[g.n(2.)]])],axis='numeric_broadcast_binding')
for c in g.cases:c['case_id']=c['case_id'].replace('w111typed-','w111modtyped-')
p=out/'typed.json';p.write_text(json.dumps(dict(schema_version='oxfunc.smart_fuzzer.scenario_seed_case_set.v0',tranche_id=g.TRANCHE,cases=g.cases,tranches=[dict(tranche_id=g.TRANCHE,case_ids=[c['case_id']for c in g.cases])]),separators=(',',':')),encoding='utf-8')
(out/'manifest.json').write_text(json.dumps({'numeric_rows':len(encoded),'typed_rows':len(g.cases),'typed_stage':'discovery, not a prior whole-surface claim','typed_sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'generator_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest()},indent=2),encoding='utf-8');print(len(encoded),len(g.cases))
